import math

def solve_cubic_for_integer_z(x, y):
    """
    Finds integer solutions z >= y for the equation:
    z^3 - (x^2y^2)z^2 + (x^3 + y^3) = 0
    """
    B = -x**2 * y**2
    D = x**3 + y**3

    solutions = []

    # Integer roots must divide D. We only consider positive divisors since z >= y >= 1.
    # If D > 0, we check positive divisors.
    if D <= 0:
        # Since x, y are positive integers, D = x^3 + y^3 must be positive.
        # This case should not happen given the problem constraints.
        return []

    # Find all positive divisors of D
    divisors = []
    for i in range(1, int(math.sqrt(D)) + 1):
        if D % i == 0:
            divisors.append(i)
            if i * i != D:
                divisors.append(D // i)

    for z in divisors:
        # Check constraint z >= y
        if z < y:
            continue

        # Check the equation: z^3 + B * z^2 + D = 0
        # z^3 - (x^2y^2)z^2 + (x^3 + y^3) = 0
        if z**3 + B * z**2 + D == 0:
            solutions.append((x, y, z))

    return solutions

# Main search loop
all_solutions = []

# Iterate over x in {1, 2, 3}
for x in [1, 2, 3]:
    # Iterate over y in {x, x+1, x+2}
    for y in range(x, min(x + 3, 5)): # Limiting y check to keep computation reasonable for this step

        # Wait, the problem statement implies x <= y <= x+2. Let's refine the range for y.
        # For x=1, y in {1, 2, 3}
        # For x=2, y in {2, 3, 4}
        # For x=3, y in {3, 4, 5}

        # Let's adjust the loop for y based on the constraint x <= y <= x+2
        y_range = range(x, x + 3)

        for y in y_range:
            solutions = solve_cubic_for_integer_z(x, y)
            if solutions:
                all_solutions.extend(solutions)

print("Found solutions (x, y, z):")
for sol in all_solutions:
    print(sol)
